r=Path('/root/tilelang-metax/race_tests/nsa/rep/v116_worker1_exact_parent_C6_C10_profile_resource_sc-16g-2');m=json.loads((r/'source_manifest.json').read_text());assert (r/'codegen_identity.exit').read_text().strip()=='0';label=sys.argv[1];ci=int(sys.argv[2]);assert label=='parent_v084' and ci in [6,10];x=next(x for x in json.loads((r/('metadata_'+label+'.json')).read_text())['records'] if x['case']==ci);src=Path(x['device_path']);host=Path(x['host_path']);assert hashlib.sha256(src.read_bytes()).hexdigest()==x['device_sha256'];out=r/'resources';out.mkdir(exist_ok=True);prefix='case'+str(ci)+'_'+label;tool=m['tools']['compiler'];assert hashlib.sha256(Path(tool['path']).read_bytes()).hexdigest()==tool['sha256'];cmd=[tool['path'],'-x','maca','-device-obj','-O3','-lineinfo','--offload-arch=xcore1000','-std=c++17','-I/root/tilelang-metax/src','-use-fast-math','-D__FAST_HALF_CVT__','-resource-usage','-o',str(out/(prefix+'.mcbin')),str(src)];(out/(prefix+'.command.json')).write_text(json.dumps({'command':cmd,'source':m['sources'][label],'device_sha256':x['device_sha256'],'NSA_attention_calls':0,'reference_checks':0},indent=2)+chr(10));assert cmd==json.loads((r/'execution_plan.json').read_text())['resource_commands'][str(ci)];a=subprocess.run(cmd,capture_output=True,text=True);raw=a.stdout+a.stderr;(out/(prefix+'.log')).write_text(raw);(out/(prefix+'.SDK.exit')).write_text(str(a.returncode)+chr(10));assert a.returncode==0
